import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { defaultAutonomy } from '@ripple/shared';
import type { Journal } from '../journal.ts';
import type { ProjectStore } from '../projects.ts';
import type { ContentStore } from '../content/store.ts';
import { demoAccount, formatStats } from '../content/team.ts';
import { addDays, day, type Item, type ItemKind, type Media } from '../content/types.ts';

// Real pictures for the demo posts, generated once with the image model and embedded,
// so the demo shows true images without calling the model on every seed.
const PICTURES: Record<string, string> = {
  warm: '',
  cool: '',
  plum: '',
};

export const DEMO_PROJECT = 'mealkinator-demo';

// A project in the middle of its life, to try the studio without spending a single model call.
// Everything here is fictional. The account posts are flagged `simulated`, as everywhere else.
export function seedDemo(o: { journal: Journal; projects: ProjectStore; content: ContentStore; mediaDir: string; repoPath: string; now?: Date }) {
  const now = o.now ?? new Date();
  const today = day(now);
  const d = (n: number) => addDays(today, n);
  const at = (n: number) => new Date(now.getTime() + n * 86_400_000).toISOString();
  const P = DEMO_PROJECT;
  const { journal, content: s } = o;

  o.projects.add({ id: P, name: 'Mealkinator (demo)', path: o.repoPath, repoUrl: '', source: 'link' });

  // --- features, replayed into the journal the way the runtime would have written them
  const feature = (id: string, title: string, summary: string, steps: Array<Record<string, unknown>>) => {
    journal.append(id, 'CREATED', { title, design: summary, projectId: P, autonomy: defaultAutonomy });
    journal.append(id, 'PLAN', { summary, needsInput: false, reason: '', steps: [{ title, detail: summary }], options: [] });
    journal.append(id, 'BUILD', { branch: `feature/${id}`, stat: '6 files changed, 212 insertions(+), 14 deletions(-)', diff: '' });
    for (const e of steps) journal.append(id, 'EVENT', e);
    if (steps.some(e => e.type === 'MERGE_DONE')) journal.append(id, 'MERGE', { commit: 'a1b2c3d', pushed: false });
  };
  const toPlan = [{ type: 'PLAN_READY' }, { type: 'APPROVE', gate: 'plan' }, { type: 'BUILD_DONE' }, { type: 'VISUAL_OK' }];
  const toMerged = [...toPlan, { type: 'APPROVE', gate: 'merge' }, { type: 'MERGE_DONE' }];
  feature('dark-mode', 'Dark mode', 'A dark theme that follows the system setting', toMerged);
  feature('recipe-search', 'Recipe search', 'Search recipes by ingredient, with filters', toPlan); // built and checked, waiting for the merge

  // --- the team's profile and standing orders
  s.setProfile(P, {
    voice: 'Warm, direct, a little self-mocking. Short sentences. No marketing jargon.',
    audience: 'Busy home cooks who hate planning meals',
    language: 'English',
    autoDraft: false,
    niche: 'meal planning app for people who hate planning',
    directives: 'Never mention pricing. Prefer short videos and carousels over long text. At most two posts a week.',
    publishMode: 'local',
  });

  // --- roadmap: one goal, two projections (the second corrects the first: the pace is slower than the plan)
  const beta = s.addMilestone({ projectId: P, title: 'Public beta', intent: 'Ten testers plan a week of meals and find recipes. The story: no more "what is for dinner".', targetDate: d(18), startDate: d(-12), scope: 4, createdAt: at(-12) });
  for (const f of ['dark-mode', 'recipe-search']) s.link(beta.id, f);
  s.addForecast({ milestoneId: beta.id, madeAt: at(-12), predictedDate: d(18), rawRemainingDays: 30, calibration: 1, done: 0, scope: 4, confidence: 'low', note: 'First projection, taken from your own plan.' });
  s.addForecast({ milestoneId: beta.id, madeAt: at(-5), predictedDate: d(24), rawRemainingDays: 21, calibration: 1.3, done: 1, scope: 4, confidence: 'medium', note: 'One of four delivered after 7 days. The pace is slower than the plan, so I correct for it: x1.3.' });

  // --- what the Scout found, and the Analyst's comparison with the account
  s.addReport(P, 'audit', {
    summary: 'For food-tech indie apps, build-in-public stories and 30-second how-tos earn the saves and shares. Release announcements on their own barely move.',
    whatWorks: [
      { format: 'behind-the-scenes', strength: 4, why: 'Builds trust and invites replies', example: '"We deleted 40% of our recipe screen. Here is why."' },
      { format: 'quick tutorial', strength: 5, why: 'The most saves of any format', example: '30-second "plan a week in one tap" screen recording' },
      { format: 'relatable meme', strength: 3, why: 'Gets shared outside the follower base', example: 'The "what is for dinner?" loop' },
    ],
    hooks: ['mistakes included', 'before / after', 'one tap', 'we asked 10 people'],
    topics: ['meal prep', 'food waste', 'solo developer', 'weeknight dinners'],
    avoid: ['release notes alone', 'feature lists'],
    sources: ['https://example.com/food-tech-content-report', 'https://example.com/indie-launch-playbook'],
  }, true, at(0)); // fictional, like everything else here: the team must say so
  const posts = demoAccount('Mealkinator', now);
  s.setAccount(P, posts);
  s.addReport(P, 'account', {
    summary: 'Your memes and behind-the-scenes posts do 5x better than release posts, which matches the field. Tutorials are the gap: none in the last month.',
    strengths: ['Humour that gets shared', 'Honest build-in-public posts'], gaps: ['No tutorials recently', 'No video at all'],
    opportunities: ['A 30-second tutorial before the beta', 'A teaser built on a mistake'], stats: formatStats(posts), postCount: posts.length,
  }, true, at(0));

  // --- content, at every stage
  const add = (i: { kind: ItemKind; title: string; brief: string } & Partial<Omit<Item, 'id' | 'projectId' | 'createdAt' | 'revisions'>>) =>
    s.addItem({ projectId: P, origin: 'user', createdAt: at(-2), ...i });
  const pic = (name: string, itemId: string, file: string) => { mkdirSync(join(o.mediaDir, itemId), { recursive: true }); writeFileSync(join(o.mediaDir, itemId, file), Buffer.from(PICTURES[name], 'base64')); return file; };
  const media = (format: Media['format'], hashtags: string[], slides: Media['slides']): Media => ({ format, hashtags, slides });

  // one idea to decide on
  add({ kind: 'teaser', title: 'The beta is 3 weeks away', brief: 'A mistakes-included teaser of the week planner.', rationale: 'Behind-the-scenes posts earn 5x your release posts, and the beta is projected in about 4 weeks.', source: 'roadmap', origin: 'ai', status: 'idea', milestoneId: beta.id, offsetDays: -21 });

  // a carousel, drafted, two pictures generated
  const carousel = add({ kind: 'social-post', title: 'We are looking for ten testers', brief: 'Call for testers, friendly, with a clear way in.', status: 'drafted', milestoneId: beta.id, offsetDays: -14 });
  s.updateItem(carousel.id, {
    draft: 'Three weeks to the beta, and we need ten testers who hate meal planning as much as we do.\n\nNo spreadsheets, no guilt. Just a week of dinners, planned in a minute.\n\nWant in? Link in bio.',
    revisions: 2,
    media: media('carousel', ['#mealprep', '#buildinpublic', '#indiedev', '#weeknightdinner', '#foodtech'], [
      { kind: 'image', visual: 'Flat lay of a weekly meal planner on a wooden table, warm morning light, pastel palette', text: 'We need 10 testers', seconds: 0, file: pic('warm', carousel.id, '1-demo.jpg') },
      { kind: 'image', visual: 'A phone showing a week of meals, pastel palette, same wooden table', text: 'Plan a week in one tap', seconds: 0, file: pic('cool', carousel.id, '2-demo.jpg') },
      { kind: 'image', visual: 'Hands holding a small sign that says beta, same wooden table', text: 'Link in bio', seconds: 0 },
    ]),
  });

  // an approved single image and a published devlog
  const single = add({ kind: 'social-post', title: 'Dark mode is here', brief: 'Short and a bit smug.', status: 'approved', fixedDate: d(1) });
  s.updateItem(single.id, { draft: 'Your midnight snack planning just got easier on the eyes.\n\nDark mode, now in Mealkinator.', revisions: 1, media: media('image', ['#darkmode', '#indiedev', '#mealprep'], [{ kind: 'image', visual: 'The app in dark mode on a phone, resting on a kitchen counter at night', text: 'Dark mode', seconds: 0, file: pic('plum', single.id, '1-demo.jpg') }]) });
  add({ kind: 'devlog', title: 'Week 3: what building taught us', brief: 'x', status: 'published', fixedDate: d(-6), draft: 'Five friends, five different ways to break the planner. Here is what we fixed first.' });
  add({ kind: 'newsletter', title: 'Beta waitlist: what to expect', brief: 'Tell the waitlist what the beta contains and how to join.', status: 'briefed', milestoneId: beta.id, offsetDays: -7 });

  // --- what the team did
  s.log(P, 'scout', 'Found 3 formats that work and 4 topics. Build-in-public and quick tutorials lead.', true, at(-0.02));
  s.log(P, 'analyst', 'Compared 14 posts with the field. Tutorials earn the most saves, memes win on shares, releases barely move.', true, at(-0.015));
  s.log(P, 'strategist', 'Proposed one piece of content. Waiting for your decision.', true, at(-0.01));
  s.log(P, 'writer', 'Drafted one accepted piece.', true, at(-0.5));
  s.addReport(P, 'synthesis', {
    headline: 'The beta is running late, and your tutorials save best.',
    points: ['Tutorials earn the most saves on your account; the Sunday-reset one leads.', 'The beta is projected after the date you want, so teasers are scheduled against the new date.', 'One proposal waits for your decision in Today.'],
    next: 'Decide on the beta teaser, it is the next thing to land.',
  }, false, at(-0.005));
  s.log(P, 'director', 'The beta is running late, and your tutorials save best.', true, at(-0.005));
  s.setAgentConfig(P, 'scout', { workers: 2 });
  s.setAgentConfig(P, 'writer', { instructions: 'Keep captions under 400 characters, warm and a little self-mocking.' });
  s.addChat(P, 'director', 'user', 'What should we do this week?', [], at(-0.004));
  s.addChat(P, 'director', 'agent', 'Post the tutorial first: it is the clearest gap. I can also have the Strategist look at the beta for teasers.', [
    { kind: 'run', label: 'Plan the beta teasers', agents: ['strategist'], brief: 'Teasers for the beta' },
    { kind: 'talk', label: 'Talk to the Strategist', agent: 'strategist' },
  ], at(-0.003));
}
